mapper.select:
SELECT id, student_id, teacher_id, title, description, start_date, end_date, created_at, updated_at
FROM goals
WHERE id = #{id}

SELECT EXISTS (
    SELECT 1 FROM goals
    WHERE student_id = #{studentId}
      AND start_date <= #{endDate}
      AND end_date >= #{startDate}

          AND id != #{excludeGoalId}

)

SELECT EXISTS (
    SELECT 1 FROM goals
    WHERE student_id = #{studentId}
      AND start_date <= #{date}
      AND end_date >= #{date}
)

mapper.update:
UPDATE goals
SET title = #{title}, description = #{description}, start_date = #{startDate}, end_date = #{endDate}
WHERE id = #{id}

UPDATE goals g
SET teacher_id = s.teacher_id
FROM students s
WHERE g.student_id = s.id
  AND g.teacher_id = #{teacherId}
  AND s.teacher_id != #{teacherId}
